"""Private ML024 reading page. No persistence or external model calls."""
import html
import json
from inno_site_chrome import navigation, footer

WORDS={'proposed':'待确认提案','draft':'草稿','confirmed':'已记录确认','unknown':'未知','conflict':'存在冲突','supported':'有资料支持','pending':'待审核','required':'需要专业批准','approved':'已记录批准','not_required_with_reason':'已说明豁免理由','requires_evidence_and_preference_review':'需结合证据与偏好审查','source_statement':'来源陈述','inferred':'分析推断','hypothesized':'待验证假设','conditional_research_only':'满足条件后可继续研究','blocked_by_constraint_conflict':'约束冲突，暂不可推进'}
KEYS={'conditions':'成立条件','key_unknowns':'关键未知','next_action':'下一步动作','route_ref':'路线','execution_authorized':'允许工程执行','status':'状态','reason':'理由','actor':'责任人','cost':'成本','budget':'预算','operating_context':'作业条件','acceptance_threshold':'验收条件','resources':'资源','responsible_actor':'责任人','value':'数值或内容','unit':'单位','nature':'内容性质','missing_reason':'待补充','id':'记录','revision':'版本'}
def friendly(value):
    if value is None:return '待确认'
    if isinstance(value,dict):
        if 'value' in value:
            content=friendly(value['value'])
            nature=WORDS.get(value.get('nature'),value.get('nature',''))
            reason=value.get('missing_reason')
            return content+('（'+nature+'）' if nature else '')+('；'+str(reason) if reason else '')
        return '；'.join(KEYS.get(k,k)+'：'+friendly(v) for k,v in value.items())
    if isinstance(value,list):return '；'.join(friendly(x) for x in value) or '暂无记录'
    if isinstance(value,bool):return '是' if value else '否'
    return WORDS.get(str(value),str(value))

def page(bundle):
    if not isinstance(bundle,dict): raise ValueError('bundle object required')
    # No external strings are inserted as markup, JS, CSS or URL.
    def dump(value):
        raw=html.escape(json.dumps(value,ensure_ascii=False,indent=2,allow_nan=False))
        labels={'notice':'使用说明','scope':'调用范围','object_scope':'经验对象','problem':'原问题','constraints':'原约束','tradeoffs':'设计取舍','goal':'研究目标','status':'确认状态','cost':'成本','budget':'预算','operating_context':'作业条件','acceptance_threshold':'验收条件','mechanism':'技术路线','conditions':'成立条件','next_action':'下一步动作','cost':'成本','constraint_status':'约束情况','missing_reason':'待补充','title':'经验名称','limitations':'适用边界','basis':'判断依据','text':'内容','recommendation_status':'推荐状态','name':'方法名称','summary':'方法说明','method_id':'方法标识','conditional_suggestions':'条件化研究建议','key_unknowns':'关键未知','question':'研究问题','hypotheses':'竞争解释','resources':'所需资源','responsible_actor':'责任人','observation':'观测内容','decision_rule':'判别方式','stop_condition':'停止条件','professional_approval':'专业批准状态','differences':'迁移差异','assumptions':'迁移假设','falsification':'证伪条件'}
        values=value if isinstance(value,list) else [value]
        cards=[]
        for row in values:
            if isinstance(row,dict):
                fields=''.join('<p><strong>'+('来源中的机制或过程' if k=='mechanism' and 'object_scope' in row else label)+'：</strong>'+html.escape(friendly(row[k]))+'</p>' for k,label in labels.items() if k in row)
                cards.append('<article>'+ (fields or '<p>暂无已确认内容，请查看记录和缺口。</p>') +'</article>')
            else: cards.append('<p>'+html.escape(str(row))+'</p>')
        return ''.join(cards)+'<details><summary>查看版本与完整记录</summary><pre>'+raw+'</pre></details>'
    titles=[('requirement','需求与确认状态'),('routes','候选路线与适用条件'),('comparison','路线比较'),('experiences','设计经验与证据'),('transfer','结构迁移假设'),('research_action','研究行动与停止条件'),('methods','本任务方法'),('feedback','已保存反馈'),('notice','错误、缺口与能力边界')]
    sections=''.join('<section id="'+k+'"><h2>'+t+'</h2>'+dump(bundle.get(k,{'missing_reason':'尚无数据'}))+'</section>' for k,t in titles)
    return '''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>企业创新研究闭环 · 本机试运行</title><link rel="stylesheet" href="/inno/portal/system.css"><style>*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--inno-canvas);color:var(--inno-text);font-family:var(--inno-font);line-height:1.65;font-size:15px}a{color:var(--inno-action);text-decoration:none}a:hover{text-decoration:underline}.pp-skip{position:fixed;left:16px;top:-100px;z-index:10;background:var(--inno-surface);padding:10px 16px}.pp-skip:focus{top:10px}.pp-nav{display:flex;align-items:center;gap:28px;padding:12px max(20px,calc((100vw - 1152px)/2));background:var(--inno-surface);border-bottom:1px solid var(--inno-border)}.pp-brand{font-size:21px;font-weight:700;white-space:nowrap;display:flex;align-items:center;gap:9px}.pp-brand span{font-size:11px;color:var(--inno-action)}.pp-links,.pp-tools{display:flex;align-items:center;gap:22px;min-width:0}.pp-links{flex:1}.pp-nav a{display:flex;align-items:center;white-space:nowrap;font-size:13px;color:var(--inno-secondary)}.pp-nav .pp-brand{font-size:21px;color:var(--inno-text)}.pp-links a[aria-current=page]{color:var(--inno-action);font-weight:600}.pp-tools{gap:16px}.pp-tools small{font-size:10px;margin-left:5px}.pp-footer{max-width:1000px;margin:32px auto;padding:24px 20px;border-top:1px solid var(--inno-border);color:var(--inno-secondary)}.pp-footer nav{display:flex;flex-wrap:wrap;gap:16px}.pp-footer p{font-size:13px}h1{font-size:30px;line-height:1.3;margin:0 0 14px}h2{font-size:21px;margin:0 0 14px}p{margin:10px 0}article{padding:14px 0;border-bottom:1px solid var(--inno-border)}article:last-of-type{border-bottom:0}summary{cursor:pointer;color:var(--inno-secondary);padding:12px 0}button{border:1px solid var(--inno-border);border-radius:9px;background:var(--inno-surface);color:var(--inno-action);font:inherit;cursor:pointer;min-height:44px}button:disabled{opacity:.5;cursor:not-allowed}select,input:not([type=checkbox]),textarea{font:inherit;border:1px solid var(--inno-border);border-radius:8px;background:var(--inno-surface);color:var(--inno-text);padding:10px;max-width:100%}select,input:not([type=checkbox]){display:block;width:100%;min-height:44px;margin:6px 0 16px}label{display:block;margin-top:12px}strong{font-weight:600}section{scroll-margin-top:20px;overflow-wrap:anywhere}@media(max-width:700px){.pp-nav{display:grid;grid-template-columns:1fr auto;gap:0 14px;padding:8px 16px}.pp-brand{grid-column:1}.pp-tools{grid-column:2;grid-row:1;gap:12px}.pp-tools a{font-size:12px}.pp-tools small{display:none}.pp-links{grid-column:1/-1;display:flex;gap:24px;overflow-x:auto;max-width:100%;padding:0 0 2px}.pp-links a{min-height:38px}.pp-nav .pp-brand{font-size:19px}.pp-brand span{font-size:10px}main{margin:22px auto!important;padding:0 16px!important}h1{font-size:26px}section{padding:16px!important;margin:16px 0!important}h2{font-size:19px}textarea{min-height:140px!important}.pp-footer{margin:22px 0;padding:20px 16px}}main{max-width:1000px;margin:32px auto;padding:0 20px}section{margin:24px 0;padding:20px;background:white;border:1px solid #ddd;border-radius:12px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:inherit;line-height:1.7}textarea{display:block;box-sizing:border-box;width:100%;min-height:220px}button{padding:10px 16px;margin:12px 8px 12px 0}a:focus,button:focus,textarea:focus{outline:3px solid #6655ee}#status{white-space:pre-wrap;overflow-wrap:anywhere}</style></head><body>'''+navigation('needs')+'''<main id="workspace-content"><h1>企业创新研究闭环</h1><label for="task-select">研究任务</label><select id="task-select" aria-label="选择研究任务"></select><p>顶部导航指向正式网站；本页为独立本机预览。</p><p>本机内部试运行。候选方案、教学数据和未确认条件需要进一步核验。</p><nav aria-label="研究页导航"><a href="#requirement">需求</a> · <a href="#routes">路线</a> · <a href="#experiences">证据</a> · <a href="#save-feedback">保存反馈</a></nav><button id="reload" type="button">刷新研究数据</button><p id="status" role="status" aria-live="polite"></p><div id="bundle">'''+sections+'''</div><section id="save-feedback"><h2>显式保存反馈</h2><p>选择具体路线并填写反馈。保存后等待审核，事实和评分不会自动改变。</p><label for="route-select">反馈路线</label><select id="route-select"></select><p id="binding-note" role="status"></p><label for="feedback-kind">反馈类型</label><select id="feedback-kind"><option value="opinion">意见</option><option value="reported_observation">报告观察</option><option value="reported_trial">报告试验结果</option></select><label for="actor-role">你的角色</label><input id="actor-role" placeholder="例如：研究人员、企业工程师"><label for="feedback-body">反馈内容及判断依据</label><textarea id="feedback-body"></textarea><label><input type="checkbox" id="internal-consent">允许本次反馈用于内部研究（不公开、不用于训练）</label><details><summary>高级：检查或编辑反馈 JSON</summary><p>编辑后仍由服务端验证版本与关联。高级编辑不会跳过主张缺失检查。</p><label><input type="checkbox" id="advanced-mode">使用下方 JSON 提交</label><label for="feedback-input">反馈 JSON</label><textarea id="feedback-input" spellcheck="false"></textarea></details><button id="save" type="button" disabled>确认保存反馈</button></section></main>'''+footer()+'<script type="application/json" id="initial-bundle">'+json.dumps(bundle,ensure_ascii=False,allow_nan=False).replace('<','\\u003c')+'</script>'+'''<script>
let currentBundle=null;
let pendingFeedbackIdentity=null;
function updateTasks(){const sel=document.getElementById('task-select');sel.replaceChildren();for(const task of currentBundle?.tasks??[]){const opt=document.createElement('option');opt.value=task.task_id;opt.textContent=task.title??task.task_id;sel.append(opt);}if(currentBundle?.current_task_id)sel.value=currentBundle.current_task_id;}

const statusEl=document.getElementById('status');
const titles={requirement:'需求与确认状态',routes:'候选路线与适用条件',comparison:'路线比较',experiences:'设计经验与证据',transfer:'结构迁移假设',research_action:'研究行动与停止条件',methods:'本任务方法',feedback:'已保存反馈',notice:'错误、缺口与能力边界'};
const words={"proposed": "待确认提案", "draft": "草稿", "confirmed": "已记录确认", "unknown": "未知", "conflict": "存在冲突", "supported": "有资料支持", "pending": "待审核", "required": "需要专业批准", "approved": "已记录批准", "requires_evidence_and_preference_review": "需结合证据与偏好审查", "source_statement": "来源陈述", "inferred": "分析推断", "hypothesized": "待验证假设"};
words.conditional_research_only='满足条件后可继续研究';words.blocked_by_constraint_conflict='约束冲突，暂不可推进';
function friendly(v){if(v===null||v===undefined)return '待确认';if(Array.isArray(v))return v.map(friendly).join('；')||'暂无记录';if(typeof v==='object'){if('value' in v)return friendly(v.value)+(v.nature?'（'+friendly(v.nature)+'）':'')+(v.missing_reason?'；'+friendly(v.missing_reason):'');const keys={conditions:'成立条件',key_unknowns:'关键未知',next_action:'下一步动作',route_ref:'路线',execution_authorized:'允许工程执行',status:'状态',reason:'理由',actor:'责任人',cost:'成本',budget:'预算',operating_context:'作业条件',acceptance_threshold:'验收条件',resources:'资源',responsible_actor:'责任人',unit:'单位',id:'记录',revision:'版本'};return Object.entries(v).map(([k,x])=>(keys[k]??k)+'：'+friendly(x)).join('；');}if(typeof v==='boolean')return v?'是':'否';return words[String(v)]??String(v);}
function show(data){currentBundle=data;updateTasks();updateRoutes();const container=document.getElementById('bundle');container.replaceChildren();for(const [key,title] of Object.entries(titles)){const section=document.createElement('section');section.id=key;const h=document.createElement('h2');h.textContent=title;section.append(h);const value=data[key]??{missing_reason:'尚无数据'};const labels={"notice": "使用说明", "scope": "调用范围", "object_scope": "经验对象", "problem": "原问题", "constraints": "原约束", "tradeoffs": "设计取舍", "goal": "研究目标", "status": "确认状态", "cost": "成本", "budget": "预算", "operating_context": "作业条件", "acceptance_threshold": "验收条件", "mechanism": "技术路线", "conditions": "成立条件", "next_action": "下一步动作", "constraint_status": "约束情况", "missing_reason": "待补充", "title": "经验名称", "limitations": "适用边界", "basis": "判断依据", "text": "内容", "recommendation_status": "推荐状态", "name": "方法名称", "summary": "方法说明", "method_id": "方法标识", "conditional_suggestions": "条件化研究建议", "key_unknowns": "关键未知", "question": "研究问题", "hypotheses": "竞争解释", "resources": "所需资源", "responsible_actor": "责任人", "observation": "观测内容", "decision_rule": "判别方式", "stop_condition": "停止条件", "professional_approval": "专业批准状态", "differences": "迁移差异", "assumptions": "迁移假设", "falsification": "证伪条件"};for(const row of (Array.isArray(value)?value:[value])){const card=document.createElement('article');if(row&&typeof row==='object'){for(const [k,label] of Object.entries(labels)){if(k in row){const p=document.createElement('p');p.textContent=(k==='mechanism'&&'object_scope' in row?'来源中的机制或过程':label)+'：'+friendly(row[k]);card.append(p);}}}else{card.textContent=String(row);}section.append(card);}const detail=document.createElement('details');const summary=document.createElement('summary');summary.textContent='查看版本与完整记录';const pre=document.createElement('pre');pre.textContent=JSON.stringify(value,null,2);detail.append(summary,pre);section.append(detail);container.append(section);}}
function selectedBinding(){const route=(currentBundle?.routes??[]).find(r=>r.id===document.getElementById('route-select').value);const rq=currentBundle?.requirement;const claim=(currentBundle?.claims??[]).find(c=>c.route_ref?.id===route?.id&&c.route_ref?.revision===route?.revision);return {rq,route,claim};}
function updateRoutes(){const sel=document.getElementById('route-select'),prior=sel.value;sel.replaceChildren();for(const r of currentBundle?.routes??[]){const opt=document.createElement('option');opt.value=r.id;opt.textContent=friendly(r.mechanism??r.id)+' · v'+r.revision;sel.append(opt);}if([...sel.options].some(o=>o.value===prior))sel.value=prior;updateBinding();}
function updateBinding(){const {rq,route,claim}=selectedBinding();const allowed=!!(rq&&route&&claim);document.getElementById('save').disabled=!allowed;document.getElementById('binding-note').textContent=allowed?'绑定需求 '+rq.id+' v'+rq.revision+' / 路线 '+route.id+' v'+route.revision+' / 主张 '+claim.id+' v'+claim.revision:'该路线尚无可绑定的主张记录，暂不能保存反馈。';}
function formFeedback(){const {rq,route,claim}=selectedBinding();if(!rq||!route||!claim)throw Error('缺少精确主张绑定');if(!document.getElementById('internal-consent').checked)throw Error('请明确内部研究用途授权');const basis=document.getElementById('feedback-body').value.trim(),role=document.getElementById('actor-role').value.trim();if(!basis||!role)throw Error('请填写角色与反馈依据');const signature=JSON.stringify([rq.id,rq.revision,route.id,route.revision,claim.id,claim.revision,document.getElementById('feedback-kind').value,role,basis]);if(pendingFeedbackIdentity?.signature!==signature)pendingFeedbackIdentity={signature,id:'FB-'+crypto.randomUUID()};return {schema_version:'0.1.0',id:pendingFeedbackIdentity.id,revision:1,requirement_ref:{id:rq.id,revision:rq.revision},route_ref:{id:route.id,revision:route.revision},claim_ref:{id:claim.id,revision:claim.revision},kind:document.getElementById('feedback-kind').value,actor_role:role,basis,authorization:{internal_research:true,public:false,training:false}};}
document.getElementById('route-select').addEventListener('change',updateBinding);
currentBundle=JSON.parse(document.getElementById('initial-bundle').textContent);updateTasks();updateRoutes();
document.getElementById('task-select').addEventListener('change',()=>{const url=new URL(window.location.href);url.searchParams.set('task',document.getElementById('task-select').value);window.location.assign(url.pathname+url.search);});
async function reload(){try{statusEl.textContent='正在读取…';const r=await fetch('/api/bundle'+window.location.search,{credentials:'same-origin',cache:'no-store'});if(!r.ok)throw Error('读取失败 HTTP '+r.status);const data=await r.json();show(data);statusEl.textContent='已读取当前数据，请核对版本。';}catch(e){statusEl.textContent=String(e)+'。当前页面内容保留，可重试。';}}
document.getElementById('reload').addEventListener('click',reload);
document.getElementById('save').addEventListener('click',async()=>{const b=document.getElementById('save');try{const generated=formFeedback();const data=document.getElementById('advanced-mode').checked?JSON.parse(document.getElementById('feedback-input').value):generated;b.disabled=true;statusEl.textContent='正在保存…';const r=await fetch('/api/feedback',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});if(!r.ok)throw Error('保存失败 HTTP '+r.status+' '+await r.text());pendingFeedbackIdentity=null;statusEl.textContent='反馈已保存，等待审核。';await reload();}catch(e){statusEl.textContent=String(e)+'。输入已保留，请修正后重试。';}finally{updateBinding();}});
</script></body></html>'''
